            border-bottom: 1px solid var(--border);
            line-height: 1.4;
            vertical-align: top;
        }
        .evo-table tbody tr:hover td { background: rgba(255,255,255,0.015); }
        .evo-table td:first-child { font-weight: 600; color: var(--text-primary); white-space: nowrap; }
        /* Skill name column — slightly dimmer, truncate on small screens */
        .evo-table td:nth-child(2) { color: var(--text-secondary); font-size: clamp(0.52rem, 0.82vw, 0.66rem); }

        .badge {
            display: inline-block;
            padding: 0.1em 0.55em;
            border-radius: 2px;
            font-size: clamp(0.5rem, 0.72vw, 0.6rem);
            font-weight: 600;
            letter-spacing: 0.05em;
            text-transform: uppercase;
            white-space: nowrap;
