        .badge-reject { background: rgba(248,113,113,0.1); border: 1px solid rgba(248,113,113,0.32); color: var(--accent-red); }

        .case-footnote {
            font-family: var(--font-mono);
            font-size: clamp(0.58rem, 0.85vw, 0.7rem);
            color: var(--text-dim);
            line-height: 1.5;
            padding-top: clamp(0.18rem, 0.5vh, 0.35rem);
