            font-size: clamp(0.82rem, 1.55vw, 1.08rem);
            font-weight: 700;
            line-height: 1.2;
        }
        .tk-desc {
            font-family: var(--font-mono);
            font-size: clamp(0.6rem, 0.98vw, 0.76rem);
            color: var(--text-secondary);
            line-height: 1.52;
